{{ config(
    tags=['m_MT_RSTD_SA_BKGS_MONTH']
) }}
{{ config(materialized='table') }}
-- Self-referencing table(s): 'MT_RSTD_SA_BKGS_MONTH_SERVICE' used as both source and target in this mapping.
-- Materialized as TABLE to snapshot source data before the target model overwrites it.
{% if var('m_MT_RSTD_SA_BKGS_MONTH_sq_mt_rstd_sa_bkgs_month_service_sql_override', '') != '' %}
{{ var('m_MT_RSTD_SA_BKGS_MONTH_sq_mt_rstd_sa_bkgs_month_service_sql_override') }}
{% else %}
-- Mapping-level SQL Query override (from Source Qualifier 'Sql Query' property)
SELECT
   BKGS.DV_DRCT_VAL_ADDED_DSTI_ORD_FLG,
   BKGS.PARTNER_PARTY_SITE_KEY AS PARTNER_SITE_PARTY_KEY,
   CASE
      WHEN BKGS.CHANNEL_BOOKING_FLG IS NULL
         THEN 'N'
      ELSE BKGS.CHANNEL_BOOKING_FLG
   END AS CHANNEL_BOOKINGS_FLG,
   CASE
      WHEN BKGS.RU_BK_PRODUCT_SUBGROUP_ID IS NULL
         THEN 'UNKNOWN'
      ELSE BKGS.RU_BK_PRODUCT_SUBGROUP_ID
   END AS BK_PRODUCT_SUBGROUP_ID,
   BKGS.PRODUCT_KEY,
   BKGS.SALES_TERRITORY_KEY,
   BKGS.SALES_REP_NUM,
   BKGS.FISCAL_YEAR_MONTH_INT AS FISCAL_YEAR_MTH_NUM_INT,
   BKGS.END_CUSTOMER_KEY,
   BKGS.BILL_TO_CUSTOMER_KEY,
   BKGS.SHIP_TO_CUSTOMER_KEY,
   BKGS.SOLD_TO_CUSTOMER_KEY,
   BKGS.BKGS_MEASURE_TRANS_TYPE_CD,
   BKGS.SERVICE_FLG,
   SUM(BKGS.EXTENDED_QTY * CASE
      WHEN SFH.ALLOCATION_PERCENTAGE IS NULL
         THEN 1
      ELSE SFH.ALLOCATION_PERCENTAGE
   END) AS EXTENDED_QTY,
   SUM(BKGS.EXTENDED_HOLD_QTY * CASE
      WHEN SFH.ALLOCATION_PERCENTAGE IS NULL
         THEN 1
      ELSE SFH.ALLOCATION_PERCENTAGE
   END) AS EXTENDED_HOLD_QTY,
   BKGS.WIPS_ORIGINATOR_ID_INT,
   SUM(BKGS.COMP_US_NET_PRICE_AMT * CASE
      WHEN SFH.ALLOCATION_PERCENTAGE IS NULL
         THEN 1
      ELSE SFH.ALLOCATION_PERCENTAGE
   END) COMP_US_NET_PRICE_AMT,
   SUM(BKGS.COMP_US_LIST_PRICE_AMT * CASE
      WHEN SFH.ALLOCATION_PERCENTAGE IS NULL
         THEN 1
      ELSE SFH.ALLOCATION_PERCENTAGE
   END) COMP_US_LIST_PRICE_AMT,
   SUM(BKGS.COMP_US_COST_AMT * CASE
      WHEN SFH.ALLOCATION_PERCENTAGE IS NULL
         THEN 1
      ELSE SFH.ALLOCATION_PERCENTAGE
   END) COMP_US_COST_AMT,
   SUM(BKGS.COMP_US_HOLD_NET_PRICE_AMT * CASE
      WHEN SFH.ALLOCATION_PERCENTAGE IS NULL
         THEN 1
      ELSE SFH.ALLOCATION_PERCENTAGE
   END) COMP_US_HOLD_NET_PRICE_AMT,
   SUM(BKGS.COMP_US_HOLD_LIST_PRICE_AMT * CASE
      WHEN SFH.ALLOCATION_PERCENTAGE IS NULL
         THEN 1
      ELSE SFH.ALLOCATION_PERCENTAGE
   END) COMP_US_HOLD_LIST_PRICE_AMT,
   SUM(BKGS.COMP_US_HOLD_COST_AMT * CASE
      WHEN SFH.ALLOCATION_PERCENTAGE IS NULL
         THEN 1
      ELSE SFH.ALLOCATION_PERCENTAGE
   END) AS COMP_US_HOLD_COST_AMOUNT,
   SUM(BKGS.COMP_US_STANDARD_PRICE_AMT * CASE
      WHEN SFH.ALLOCATION_PERCENTAGE IS NULL
         THEN 1
      ELSE SFH.ALLOCATION_PERCENTAGE
   END) COMP_US_STANDARD_PRICE_AMT,
   BKGS.CORPORATE_BOOKINGS_FLG,
   SUM(BKGS.TRADE_IN_AMT * CASE
      WHEN SFH.ALLOCATION_PERCENTAGE IS NULL
         THEN 1
      ELSE SFH.ALLOCATION_PERCENTAGE
   END) AS TRADE_IN_AMT,
   SUM((CASE
      WHEN RTRIM(BK_ALLOCATED_SERVC_GROUP_ID) IN (COLLATE('AS TRANSACTION', 'en-ci-rtrim'), COLLATE('AS FIXED', 'en-ci-rtrim'))
         THEN COMP_US_NET_PRICE_AMT
      ELSE BKGS.DV_ANNUALIZED_US_NET_AMT
   END) * CASE
      WHEN SFH.ALLOCATION_PERCENTAGE IS NULL
         THEN 1
      ELSE SFH.ALLOCATION_PERCENTAGE
   END) DV_ANNUALIZED_US_NET_AMT,
   SUM((CASE
      WHEN RTRIM(BK_ALLOCATED_SERVC_GROUP_ID) IN (COLLATE('AS TRANSACTION', 'en-ci-rtrim'), COLLATE('AS FIXED', 'en-ci-rtrim'))
         THEN 0
      ELSE BKGS.DV_MULTIYEAR_US_NET_AMT
   END) * CASE
      WHEN SFH.ALLOCATION_PERCENTAGE IS NULL
         THEN 1
      ELSE SFH.ALLOCATION_PERCENTAGE
   END) DV_MULTIYEAR_US_NET_AMT,
   BKGS.DV_REVENUE_RECOGNITION_FLG,
   BKGS.DV_NET_SPREAD_FLG,
   BKGS.DV_ATTRIBUTION_CD,
   DV_PRODUCT_KEY,
   CASE
      WHEN SFH.BK_SERVICE_CATEGORY_ID IS NULL
         THEN 'UNKNOWN'
      ELSE SFH.BK_SERVICE_CATEGORY_ID
   END AS BK_SERVICE_CATEGORY_ID,
   BKGS.DV_FMV_FLG,
   BKGS.CANCEL_CODE AS CANCEL_CD,
   BKGS.ADJUSTMENT_CODE AS BK_SALES_ADJ_CD,
   BKGS.DSV_FLG /* Added as part of  Q1FY16 DSV **/,
   /* Added the below columns as part of  RO project  Q3FY17**/
   BKGS.XCAT_FLG,
   BKGS.BK_OFFER_TYPE_NAME,
   BKGS.RECURRING_OFFER_FLG,
   BKGS.ELA_FLG,
   BKGS.DV_RECURRING_OFFER_CD
FROM
   (
      SELECT
         BKG_CHNL_MSR.DV_DRCT_VAL_ADDED_DSTI_ORD_FLG DV_DRCT_VAL_ADDED_DSTI_ORD_FLG,
         BKG_CHNL_MSR.PARTNER_SITE_PARTY_KEY PARTNER_PARTY_SITE_KEY,
         CASE
            WHEN BKG_CHNL_MSR.CHANNEL_BOOKINGS_FLG IS NULL
               THEN 'N'
            ELSE BKG_CHNL_MSR.CHANNEL_BOOKINGS_FLG
         END CHANNEL_BOOKING_FLG,
         CASE
            WHEN COLLATE(GOODS_OR_SERVICE_TYPE, 'en-ci-rtrim') = 'GOODS'
               THEN PRD.RU_BK_PRODUCT_SUBGROUP_ID
            ELSE PRD.RU_BK_SERVICE_PROD_SUBGROUP_ID
         END RU_BK_PRODUCT_SUBGROUP_ID,
         BKGS_MSR.PRODUCT_KEY,
         BKGS_MSR.SALES_TERRITORY_KEY,
         BKGS_MSR.SALES_REP_NUMBER SALES_REP_NUM,
         FD2Y.FISCAL_YEAR_MONTH_INT,
         BKGS_MSR.END_CUSTOMER_KEY,
         BKGS_MSR.BILL_TO_CUSTOMER_KEY,
         BKGS_MSR.SHIP_TO_CUSTOMER_KEY,
         BKGS_MSR.SOLD_TO_CUSTOMER_KEY,
         BKGS_MSR.BKGS_MEASURE_TRANS_TYPE_CODE BKGS_MEASURE_TRANS_TYPE_CD,
         BKGS_MSR.SERVICE_FLG,
         BKGS_MSR.DD_EXTENDED_QUANTITY EXTENDED_QTY,
         BKGS_MSR.DD_EXTENDED_HOLD_QUANTITY EXTENDED_HOLD_QTY,
         BKGS_MSR.WIPS_ORIGINATOR_ID_INT,
         DD_COMP_US_NET_PRICE_AMOUNT COMP_US_NET_PRICE_AMT,
         DD_COMP_US_LIST_PRICE_AMOUNT COMP_US_LIST_PRICE_AMT,
         DD_COMP_US_COST_AMOUNT COMP_US_COST_AMT,
         DD_COMP_US_HOLD_NET_PRICE_AMT COMP_US_HOLD_NET_PRICE_AMT,
         DD_COMP_US_HOLD_LIST_PRICE_AMT COMP_US_HOLD_LIST_PRICE_AMT,
         DD_COMP_US_HOLD_COST_AMOUNT COMP_US_HOLD_COST_AMT,
         DD_COMP_US_STANDARD_PRICE_AMT COMP_US_STANDARD_PRICE_AMT,
         BKGS_MSR.CORPORATE_BOOKINGS_FLG CORPORATE_BOOKINGS_FLG,
         BKGS_MSR.TRADE_IN_AMOUNT TRADE_IN_AMT,
         DV_ANNUALIZED_US_NET_AMT,
         DV_MULTIYEAR_US_NET_AMT,
         BKGS_MSR.DV_REVENUE_RECOGNITION_FLG DV_REVENUE_RECOGNITION_FLG,
         BKGS_MSR.DV_NET_SPREAD_FLG DV_NET_SPREAD_FLG,
         BKGS_MSR.DV_ATTRIBUTION_CD DV_ATTRIBUTION_CD,
         DV_PRODUCT_KEY,
         BKGS_MSR.DV_SALES_ORDER_LINE_KEY SALES_ORDER_LINE_KEY,
         CANCEL_CODE,
         BKGS_MSR.DV_FMV_FLG,
         BKGS_MSR.ADJUSTMENT_CODE,
         BKGS_MSR.DSV_FLG /* Added as part of  Q1FY16 DSV **/,
         /* Added the below columns as part of  RO project  Q3FY17**/
         BKGS_MSR.XCAT_FLG,
         BKGS_MSR.BK_OFFER_TYPE_NAME,
         BKGS_MSR.RECURRING_OFFER_FLG,
         BKGS_MSR.ELA_FLG,
         BKGS_MSR.DV_RECURRING_OFFER_CD
      FROM
         {{ var('m_MT_RSTD_SA_BKGS_MONTH_SLSORDVWDB') }}.MT_RSTD_BKGS_MEASURE BKGS_MSR
         INNER JOIN
            {{ var('m_MT_RSTD_SA_BKGS_MONTH_COMREFVWDB') }}.R_PRODUCTS_FIN PRD
            ON BKGS_MSR.PRODUCT_KEY = PRD.ITEM_KEY
         INNER JOIN
            {{ var('m_MT_RSTD_SA_BKGS_MONTH_SLSORDVWDB') }}.N_BKGS_CHNL_MEASURE BKG_CHNL_MSR
            ON BKGS_MSR.BOOKINGS_MEASURE_KEY = BKG_CHNL_MSR.BOOKINGS_MEASURE_KEY
            AND BKGS_MSR.BOOKINGS_PROCESS_DATE = BKG_CHNL_MSR.BOOKINGS_PROCESS_DATE
            AND BKGS_MSR.BKGS_MEASURE_TRANS_TYPE_CODE = BKG_CHNL_MSR.BKGS_MEASURE_TRANS_TYPE_CODE
         INNER JOIN
            {{ var('m_MT_RSTD_SA_BKGS_MONTH_COMREFVWDB') }}.R_FISCAL_DAY_TO_YEAR FD2Y
            ON BKGS_MSR.BOOKINGS_PROCESS_DATE = FD2Y.CALENDAR_DATE
            AND FD2Y.FISCAL_YEAR_AGE BETWEEN 0 AND 3
      --AND FD2Y.FISCAL_YEAR_MONTH_INT=201411
      /*INNER JOIN    SLSORDVWDB.N_SALES_ORDER_LINE_TV SOL
      ON  SOL.SALES_ORDER_LINE_KEY=CASE WHEN BKGS_MSR.SALES_ORDER_LINE_KEY<=-1000000 THEN -9999 ELSE BKGS_MSR.SALES_ORDER_LINE_KEY END 
      AND  SOL.END_TV_DATETIME = '3500-01-01 00:00:00'*/
      WHERE
         COLLATE(BKGS_MSR.DV_REVENUE_RECOGNITION_FLG, 'en-ci-rtrim') = 'Y'
         AND COLLATE(BKGS_MSR.SERVICE_FLG, 'en-ci-rtrim') = 'Y'
   ) BKGS
   LEFT OUTER JOIN
      (
         SELECT
            LNK.SALES_ORDER_LINE_KEY,
            LNK.BK_PRODUCT_SUBGROUP_ID,
            ALLOC.BK_SERVICE_CATEGORY_ID,
            ALLOC.ALLOCATION_PERCENTAGE,
            ALLOC.BK_ALLOCATED_SERVC_GROUP_ID,
            LNK.DV_ATTRIBUTION_CD
         FROM
            {{ var('m_MT_RSTD_SA_BKGS_MONTH_SLSORDVWDB') }}.MT_CS_DEAL_SO_LINE_LINK LNK,
            {{ var('m_MT_RSTD_SA_BKGS_MONTH_COMREFVWDB') }}.MT_CS_DEAL_SVC_FIN_HIER_ALLOC ALLOC
         WHERE
            LNK.APPROVED_DEAL_ID = ALLOC.APPROVED_DEAL_ID
            AND LNK.CS_DEAL_PRDT_SUB_GROUP_ID = ALLOC.BK_PRODUCT_SUBGROUP_ID
            AND COLLATE(BK_ALLOCATED_SERVC_GROUP_ID, 'en-ci-rtrim') <> 'UNKNOWN'
      ) SFH
      ON SFH.SALES_ORDER_LINE_KEY = BKGS.SALES_ORDER_LINE_KEY
      AND SFH.BK_PRODUCT_SUBGROUP_ID = BKGS.RU_BK_PRODUCT_SUBGROUP_ID
      AND SFH.DV_ATTRIBUTION_CD = BKGS.DV_ATTRIBUTION_CD
GROUP BY
   BKGS.DV_DRCT_VAL_ADDED_DSTI_ORD_FLG,
   BKGS.PARTNER_PARTY_SITE_KEY,
   CHANNEL_BOOKING_FLG,
   BKGS.RU_BK_PRODUCT_SUBGROUP_ID,
   BKGS.PRODUCT_KEY,
   BKGS.SALES_TERRITORY_KEY,
   BKGS.SALES_REP_NUM,
   BKGS.FISCAL_YEAR_MONTH_INT,
   BKGS.END_CUSTOMER_KEY,
   BKGS.BILL_TO_CUSTOMER_KEY,
   BKGS.SHIP_TO_CUSTOMER_KEY,
   BKGS.SOLD_TO_CUSTOMER_KEY,
   BKGS.BKGS_MEASURE_TRANS_TYPE_CD,
   BKGS.SERVICE_FLG,
   BKGS.WIPS_ORIGINATOR_ID_INT,
   BKGS.CORPORATE_BOOKINGS_FLG,
   BKGS.DV_REVENUE_RECOGNITION_FLG,
   BKGS.DV_NET_SPREAD_FLG,
   BKGS.DV_ATTRIBUTION_CD,
   DV_PRODUCT_KEY,
   BK_SERVICE_CATEGORY_ID,
   BKGS.CANCEL_CODE,
   BKGS.DV_FMV_FLG,
   BKGS.ADJUSTMENT_CODE,
   BKGS.DSV_FLG /* Added as part of  Q1FY16 DSV **/,
   BKGS.XCAT_FLG,
   BKGS.BK_OFFER_TYPE_NAME,
   BKGS.RECURRING_OFFER_FLG,
   BKGS.ELA_FLG,
   BKGS.DV_RECURRING_OFFER_CD
{% endif %}